    /// <summary>
    /// MPJ-21310
    /// Check if substitutions (extended functionality) should be applied to this line.
    /// </summary>
    /// <returns>True if subs enabled</returns>
    public boolean metSubstitutionsActive()
    {
        boolean         ret = true;
        SalesTable      metSalesTableStd = this.salesTable();

        if(!metSalesTableStd.custTable_CustAccount().METSalesItemSubstitutionEnabled)
        {
            ret = false;
        }

        // TODO - Dependency on pending 'sales type' modification. Check 'substitutes enabled' flag.
        return ret;
    }

    /// <summary>
    /// MPJ-21275 - Backorders
    /// Checks if backorders are allowed to this line.
    /// </summary>
    /// <returns>True if backorders are allowed</returns>
    public boolean metAllowBackorders()
    {
        boolean             allowBackorders;
        SalesTable          salestable  = this.salesTable();
        
        allowBackorders = (METSalesOrderTypes::find(salesTable.METSalesOrderType).BackordersAllowed) ||
                        (METCustTable::find(salesTable.CustAccount).AllowBackOrders &&
                        MetItemSiteSettingsSetup::find(this.ItemId, this.inventDim().InventSiteId).AllowBackOrders);

        return allowBackorders;
    }

/// <summary>
/// Find corresponding METSalesLine (additional fields).
/// </summary>
/// <returns>METSalesLine record</returns>
public METSalesLine metSalesLine()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METSalesLine));
}

/// <summary>
/// pack the METSalesLine record fields
/// </summary>
/// <param name = "_metSalesLine">Record buffer of METSalesLine to pack</param>
public void metPackMETSalesLine(METSalesLine _metSalesLine)
{
    _metSalesLine.SalesLine = this.RecId;
    this.SysExtensionSerializerMap::packExtensionTable(_metSalesLine);
}

    /// <summary>
    /// Get InventTable buffer related to the SalesLine with limited fields
    /// </summary>
    /// <returns>InventTable buffer with limited fields</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public InventTable metInventTableLimitedFields()
    {
        InventTable     metInventTableLimitedFields;
        select firstonly Product, NetWeight, TaraWeight, UnitVolume
            from metInventTableLimitedFields
            where metInventTableLimitedFields.ItemId == this.ItemId;

        return metInventTableLimitedFields;
    }

/// <summary>
/// Get Metcash item type for item on the SalesLine.
/// </summary>
/// <returns>Metcash item type</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METItemTypes displayMETItemType()
{
    return InventTable::metGetItemType(this.ItemId, this.inventDim().InventSiteId);
}

/// <summary>
/// Get the warehouse category.
/// </summary>
/// <returns>Warehouse category</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METFilterCodeone displayMETFilterCodeOne()
{
    return InventTable::metGetFilterCodeOne(this.ItemId, this.inventDim().InventSiteId);
}

/// <summary>
/// Get Order split category code for item on the SalesLine.
/// </summary>
/// <returns>Order split category code</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METOSCCode displayMETOSCCode()
{
    return InventTable::metGetOSCCode(this.ItemId, this.inventDim());
}

/// <summary>
/// To get grossWeight for the SalesLine Item.
/// </summary>
/// <returns>GrossWeight of salesLine Item</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METGrossWeight displayMETGrossWeight()
{
    return  METWHSPhysDimUOMSite::convertWeight(this.ItemId, this.SalesQty, this.SalesUnit, this.inventDim());
}

/// <summary>
/// To get unitVolume for the SalesLine Item.
/// </summary>
/// <returns>unitVolume of salesLine Item</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METUOMVolume displayMETUnitVolume()
{
    return METWHSPhysDimUOMSite::convertVolume(this.ItemId, this.SalesQty, this.SalesUnit, this.inventDim());
}

/// <summary>
/// Calculate total number of cases for the sales order line quantity.
/// </summary>
/// <returns>Total cases of salesLine Item</returns>
[SysClientCacheDataMethod(true)]
public display InventQty metTotalcases()
{
    return EcoResProductUnitConverter::convertForReleasedProduct(
        this.ItemId,
        this.InventDimId,
        this.SalesQty,
        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.SalesUnit),
        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(METConstants::unitcase),
        NoYes::Yes,
        NoYes::No);
}

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <returns>Number of cases</returns>
[SysClientCacheDataMethod(true)]
public display METCase displayMETcases()
{
    return any2Int(this.metTotalcases());
}

/// <summary>
/// To calculate and display the number of broken cases for the sales order line quantity.
/// </summary>
/// <returns>Number of broken cases</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METBrokenCase displayMETBrokenCase()
{
    //Show broken case for each line that equals to the ordered quantity for sell units that are in “ea”. 
    //For any other sell units broken case=0
    return this.SalesUnit == METConstants::unitEach ? this.SalesQty : 0;
}

/// <summary>
/// Copy profit centre dimension  from warehouse
/// </summary>
/// <param name = "_inventDim">InventDIm</param>
public void metCopyDimensionfromWarehosue(InventDim _inventDim = this.inventDim())
{
    DimensionDefault            dimensionWarehouse;
    //Copy dimension from Warehouse if exists
    if (_inventDim.InventLocationId)
    {
        dimensionWarehouse = InventLocation::changeDimension(this.DefaultDimension, _inventDim.InventLocationId);
    }
    DimensionDisplayValue dimensionValue = METHelper::getDimensionValue(dimensionWarehouse, METConstants::profitCentre);
    if(dimensionValue)
    {
        this.DefaultDimension = dimensionWarehouse;
    }
    else
    {
        this.DefaultDimension = InventSite::changeDimension(this.DefaultDimension, _inventDim.InventSiteId);
    }
}

    /// <summary>
    /// Method to determine if conversion exists  between the purchase and warehouse units
    /// </summary>
    /// <param name = "_conversionQty">Qty to convert</param>
    /// <param name = "_convertFromUOM">UOM to convert from</param>
    /// <param name = "_itemId">item id</param>
    /// <param name = "_inventLocationId">the warehouse location</param>
    /// <param name = "_inventSiteId">the inventory site</param>
    /// <returns>True if UOM conversion is found/else false and warehouse unit and the warehouse quantity</returns>
    public static container metGetQtyWeightVolume(Qty _conversionQty, Itemid _itemId, InventDim _inventDim)
    {
        Qty                         reservedQty;
        METCase                     caseQty;
        UnitOfMeasureSymbol         inventoryUnit, warehouseUnit;
        Weight                      weight;
        Volume                      volume;

        InventTableModule           inventTableModule;
        InventDim                   inventDim;

        Factor                      factor;

        if(!_inventDim)
        {
            return [1, _conversionQty];
        }

        warehouseUnit = METInventLocation::getWarehouseUnit(_itemId, _inventDim);

        if (warehouseUnit == METConstants::emptyString)
        {
            return [1, _conversionQty];
        }
             
        
        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId      == _itemId
                && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        if(inventoryUnit == warehouseUnit)
        {
            caseQty     = 1;
            reservedQty = _conversionQty;
        }
        else
        {
            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        _itemId,
                        _inventDim.inventDimId,
                        _conversionQty,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventoryUnit),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(warehouseUnit),
                        NoYes::No,
                        NoYes::No);

            if(factor)
            {
                reservedQty     = factor;
                caseQty = _conversionQty / factor;
            }
        }

        weight  =   METWHSPhysDimUOMSite::convertWeight(_itemId, reservedQty, warehouseUnit, _inventDim);
        volume  =   METWHSPhysDimUOMSite::convertVolume(_itemId, reservedQty, warehouseUnit, _inventDim);

        return [caseQty, reservedQty, weight, volume];
    }
